class LockGuard {
public:
    LockGuard() { /* Acquire lock */ }
    ~LockGuard() { /* Release lock */ }
};

class DatabaseHandle {
public:
    DatabaseHandle() {}
    ~DatabaseHandle() { /* Close DB connection */ }
};

// RAII demonstration using automatic storage duration
void scoped_lock_example() {
    LockGuard lock; 
    // Lock automatically released on scope exit, even if exception thrown.
}

// RAII demonstration using Smart Pointers (Dynamic allocation)
void smart_pointer_example() {
    std::unique_ptr<DatabaseHandle> db_conn = 
        std::make_unique<DatabaseHandle>();

    // DB connection automatically closed when db_conn leaves scope.
}
